import { BaseComponent } from "../../utils/baseElement";
import { Cell } from "../Cell/Cell";
import styles from "./GameBoard.module.scss";

class GameBoard extends BaseComponent {
  /**
   *
   * @param {string} tag
   * @param {string} className
   * @param {number} width
   * @param {number} height
   */
  constructor(tag, className, width, height) {
    super({ tag, className });
    this.width = width;
    this.height = height;
    const size = this.getGameBoardSize(this.width);
    this.getNode().classList.add(styles[size]);
    this.addCells();
  }

  addCells() {
    const cells = Array.from({ length: this.calculateNumberOfCells() }).map(
      () => {
        const cell = new Cell();
        return cell.getNode();
      },
    );
    this.getNode().append(...cells);
  }

  calculateNumberOfCells() {
    return this.width * this.height;
  }

  /**
   *
   * @param {number} width
   * @returns {string}
   */
  getGameBoardSize(width) {
    const size = {
      5: "small",
      10: "medium",
      15: "hard",
    };

    return size[width];
  }
}

export { GameBoard }; // main
